function normalizeText(str) {
  return (str || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
}

function matchCatalog(text) {
  const norm = normalizeText(text);
  const tokens = norm.replace(/[^a-z0-9]/g, ' ').split(/\s+/).filter(t => t.length >= 3);
  const stopWords = new Set([
    'hola', 'buenos', 'buenas', 'dias', 'tardes', 'noches', 'como', 'estas', 'esta',
    'que', 'tipo', 'de', 'el', 'la', 'los', 'las', 'un', 'una', 'unos', 'unas',
    'hacen', 'hace', 'tienen', 'tiene', 'realizan', 'realiza', 'veo', 'quisiera',
    'saber', 'precio', 'costo', 'valor', 'cuanto', 'vale', 'cuesta', 'para', 'por',
    'favor', 'gracias', 'laboratorio', 'examen', 'examenes', 'analisis', 'prueba', 'pruebas'
  ]);
  const keywords = tokens.filter(t => !stopWords.has(t));
  if (keywords.length === 0) return [];

  const matched = [];
  const seen = new Set();

  for (const item of MIRROR_CATALOG) {
    const nameNorm = normalizeText(item.n);
    const synsNorm = (item.s || []).map(normalizeText);

    for (const kw of keywords) {
      let hit = nameNorm.includes(kw) || synsNorm.some(s => s.includes(kw));
      if (!hit && kw.endsWith('s') && kw.length > 3) {
        const sing = kw.slice(0, -1);
        hit = nameNorm.includes(sing) || synsNorm.some(s => s.includes(sing));
      }
      if (hit && !seen.has(item.n)) {
        seen.add(item.n);
        matched.push(item);
        break;
      }
    }
  }
  return matched;
}

